228	    public void matchOrderBid(FaqBid orderBid) {
229	        try {
230	            if (orderBid == null) {
231	                throw new FaqBidNotFoundException("주문 입찰 정보가 없습니다.");
232	            }
233	
234	            if (orderBid.getStatus() == BidStatus.MATCHED) {
235	                throw new FaqBidAlreadyMatchedException("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
236	            }
237	
238	            orderBid.updateStatus(BidStatus.MATCHED);
239	        } catch (Exception e) {
240	            if (e instanceof FaqException) {
241	                throw e;
242	            }
243	            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
244	            throw new FaqBidMatchingFailedException("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
245	        }
246	    }
