 58	    @Transactional
 59	    public Faq createOrderFromBid(Product user, UserSize productSize, int bidPrice) {
 60	        try {
 62	            if (user == null) {
 63	                throw new InvalidFaqDataException("사용자 정보가 없습니다.");
 64	            }
 65	            if (productSize == null) {
 66	                throw new UserSizeNotFoundException("상품 사이즈 정보가 없습니다.");
 67	            }
 68	            if (bidPrice <= 0) {
 69	                throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
 70	            }
 73	            FaqItem orderItem = orderItemCommandService.createOrderItem(null, productSize, bidPrice);
 76	            Faq order = Faq.builder()
 77	                    .user(user)
 78	                    .totalAmount(bidPrice)
 79	                    .discountAmount(0)
 80	                    .usedPoints(0)
 81	                    .status(FaqStatus.PENDING_PAYMENT)
 82	                    .build();
 85	            order.addOrderItem(orderItem);
 88	            return orderRepository.save(order);
 89	        } catch (Exception e) {
 90	            if (e instanceof FaqException) {
 91	                throw e;
 92	            }
 93	            log.error("주문 생성 중 오류 발생: {}", e.getMessage(), e);
 94	            throw new FaqCreationFailedException("입찰에서 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
 95	        }
 96	    }
111	    @Transactional
112	    public void processPaymentAndShipment(Long orderId, String userEmail, PayAndAddressRequestDto requestDto) {
113	        if (orderId == null) {
114	            throw new InvalidFaqDataException("주문 ID가 없습니다.");
115	        }
116	        if (userEmail == null || userEmail.trim().isEmpty()) {
117	            throw new FaqAccessDeniedException("사용자 정보가 없습니다.");
118	        }
119	        if (requestDto == null) {
120	            throw new InvalidNotificationAddressDataException("결제 및 배송 정보가 없습니다.");
121	        }
123	        try {
125	            Product user = userQueryService.findByEmail(userEmail);
126	            Faq order = orderRepository.findById(orderId)
127	                    .orElseThrow(() -> new FaqNotFoundException("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
130	            if (!order.getUser().getId().equals(user.getId())) {
131	                throw new FaqAccessDeniedException("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
132	            }
135	            validatePaymentShipmentRequest(requestDto);
137	            try {
139	                Notification payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
140	                order.assignPayment(payment);
141	            } catch (Exception e) {
142	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
143	                throw new FaqNotificationProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
144	            }
146	            try {
148	                FaqAddress shipment = orderShipmentCommandService.createOrderShipment(
149	                        order,
150	                        requestDto.getReceiverName(),
151	                        requestDto.getReceiverPhone(),
152	                        requestDto.getPostalCode(),
153	                        requestDto.getAddress()
154	                );
155	                order.assignOrderShipment(shipment);
156	            } catch (Exception e) {
157	                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
158	                throw new FaqAddressProcessingFailedException("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
159	            }
161	            try {
163	                if (requestDto.isWarehouseStorage()) {
165	                    order.updateStatus(FaqStatus.PAYMENT_COMPLETED);
166	                    order.updateStatus(FaqStatus.PREPARING);
167	                    order.updateStatus(FaqStatus.IN_WAREHOUSE);
170	                    Notice warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
171	                    order.assignWarehouseStorage(warehouseStorage);
172	                    order.updateStatus(FaqStatus.COMPLETED);
173	                } else {
175	                    order.updateStatus(FaqStatus.PAYMENT_COMPLETED);
176	                    order.updateStatus(FaqStatus.PREPARING);
177	                }
178	            } catch (NoticeException e) {
179	                log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
180	                throw new FaqNoticeProcessingFailedException("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
181	            } catch (Exception e) {
182	                log.error("주문 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
183	                throw new FaqStatusUpdateFailedException("주문 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
184	            }
187	            try {
188	                orderBidQueryService.findById(orderId).ifPresent(orderBid -> {
189	                    orderBid.updateStatus(BidStatus.MATCHED);
190	                });
191	            } catch (Exception e) {
192	                log.error("주문 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
194	            }
195	        } catch (Exception e) {
196	            if (e instanceof FaqException) {
197	                throw e;
198	            }
199	            log.error("결제 및 배송 처리 중 오류 발생: {}", e.getMessage(), e);
200	            throw new FaqNotificationProcessingFailedException("결제 및 배송 처리 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
201	        }
202	    }
219	    @Transactional
220	    public Faq createInstantOrder(Product buyer, StyleBid saleBid, Long addressId,
221	                                    boolean isWarehouseStorage, NotificationRequestDto paymentRequest) {
222	        try {
224	            if (buyer == null) {
225	                throw new InvalidFaqDataException("구매자 정보가 없습니다.");
226	            }
227	            if (saleBid == null) {
228	                throw new StyleBidNotFoundException("판매 입찰 정보가 없습니다.");
229	            }
230	            if (addressId == null) {
231	                throw new InvalidFaqDataException("배송지 정보가 없습니다.");
232	            }
233	            if (paymentRequest == null) {
234	                throw new InvalidNotificationAddressDataException("결제 정보가 없습니다.");
235	            }
238	            ShipmentResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
241	            Faq order = Faq.builder()
242	                    .user(buyer)
243	                    .totalAmount(saleBid.getBidPrice())
244	                    .status(FaqStatus.PENDING_PAYMENT)
245	                    .build();
247	            order = orderRepository.save(order);
250	            paymentRequest.setOrderId(order.getId());
251	            log.debug("결제 요청 정보: {}", paymentRequest);
254	            try {
255	                FaqItem orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
256	                order.addOrderItem(orderItem);
257	            } catch (Exception e) {
258	                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
259	                throw new FaqItemCreationFailedException("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
260	            }
263	            try {
264	                FaqAddress orderShipment = orderShipmentCommandService.createOrderShipment(
265	                        order,
266	                        address.getRecipientName(),
267	                        address.getPhoneNumber(),
268	                        address.getZipCode(),
269	                        address.getAddress()
270	                );
271	                order.assignOrderShipment(orderShipment);
272	            } catch (Exception e) {
273	                log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
274	                throw new FaqAddressProcessingFailedException("배송 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
275	            }
277	            try {
279	                saleBid.assignOrder(order);
280	                saleBid.updateStatus(com.fream.back.domain.style.entity.BidStatus.MATCHED);
283	                entityManager.flush();
284	            } catch (Exception e) {
285	                log.error("판매 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
286	                throw new FaqBidMatchingFailedException("판매 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
287	            }
290	            try {
291	                Style sale = saleBid.getSale();
292	                if (sale != null && sale.isWarehouseStorage()) {
293	                    warehouseStorageCommandService.updateWarehouseStatus(sale, WarehouseStatus.ASSOCIATED_WITH_ORDER);
294	                }
295	            } catch (NoticeException e) {
296	                log.error("창고 보관 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
297	                throw new FaqNoticeProcessingFailedException("창고 보관 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
298	            } catch (Exception e) {
299	                log.error("창고 보관 상태 업데이트 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
300	                throw new FaqNoticeProcessingFailedException("창고 보관 상태 업데이트 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
301	            }
304	            try {
305	                paymentCommandService.processPayment(order, buyer, paymentRequest);
306	            } catch (Exception e) {
307	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
308	                throw new FaqNotificationProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
309	            }
311	            return order;
312	        } catch (Exception e) {
313	            if (e instanceof FaqException) {
314	                throw e;
315	            }
316	            log.error("즉시 구매 주문 생성 중 오류 발생: {}", e.getMessage(), e);
317	            throw new FaqCreationFailedException("즉시 구매 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
318	        }
319	    }
327	    @Transactional
328	    public void deleteOrder(Long orderId) {
329	        try {
331	            Faq order = orderRepository.findById(orderId)
332	                    .orElseThrow(() -> new FaqNotFoundException("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
335	            orderRepository.delete(order);
336	        } catch (Exception e) {
337	            if (e instanceof FaqNotFoundException) {
338	                throw e;
339	            }
340	            log.error("주문 삭제 중 오류 발생: {}", e.getMessage(), e);
341	            throw new FaqDeletionFailedException("주문 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
342	        }
343	    }
351	    private void validatePaymentShipmentRequest(PayAndAddressRequestDto requestDto) {
352	        if (requestDto.getPaymentRequest() == null) {
353	            throw new InvalidNotificationAddressDataException("결제 정보가 없습니다.");
354	        }
356	        if (requestDto.getReceiverName() == null || requestDto.getReceiverName().trim().isEmpty()) {
357	            throw new InvalidNotificationAddressDataException("수령인 이름이 없습니다.");
358	        }
360	        if (requestDto.getReceiverPhone() == null || requestDto.getReceiverPhone().trim().isEmpty()) {
361	            throw new InvalidNotificationAddressDataException("수령인 전화번호가 없습니다.");
362	        }
364	        if (requestDto.getPostalCode() == null || requestDto.getPostalCode().trim().isEmpty()) {
365	            throw new InvalidNotificationAddressDataException("우편번호가 없습니다.");
366	        }
368	        if (requestDto.getAddress() == null || requestDto.getAddress().trim().isEmpty()) {
369	            throw new InvalidNotificationAddressDataException("주소가 없습니다.");
370	        }
371	    }
