275	            log.error("계좌이체 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
276	                    order.getId(), e.getMessage(), e);
277	            throw new NotificationProcessingException("계좌이체 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
