341	    private void handleRefundIfNecessary(Notification payment) {
342	        Instant start = Instant.now();
343	        try {
344	            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
345	                log.warn("환불 처리 불가: 결제ID={}, 결제식별자(impUid)가 없습니다.", payment.getId());
346	                return;
347	            }
349	            log.info("결제 환불 처리 시작: 결제ID={}, impUid={}", payment.getId(), payment.getImpUid());
351	            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());
353	            if (refundSuccess) {
354	                payment.updateStatus(NotificationStatus.REFUNDED);
355	                paymentRepository.save(payment);
356	                log.info("결제 환불 처리 완료: 결제ID={}, 상태=REFUNDED", payment.getId());
357	            } else {
358	                log.error("결제 환불 처리 실패: 결제ID={}", payment.getId());
359	                throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED,
360	                        "환불 요청이 실패했습니다. 관리자에게 문의하세요.");
361	            }
364	            Instant end = Instant.now();
365	            Duration duration = Duration.between(start, end);
366	            log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());
367	        } catch (NotificationException e) {
368	            throw e;
369	        } catch (Exception e) {
370	            log.error("결제 환불 처리 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
371	                    payment.getId(), e.getMessage(), e);
372	            throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED,
373	                    "환불 처리 중 오류가 발생했습니다: " + e.getMessage());
374	        }
375	    }
383	    private void notifyUsersAndUpdateSaleStatus(Faq order, Notification payment) {
384	        try {
385	            log.info("결제 관련 알림 및 판매 상태 업데이트 시작: 주문ID={}", order.getId());
388	            FaqBid orderBid = order.getOrderBid();
389	            if (orderBid == null) {
391	                StyleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
392	                if (saleBid == null) {
393	                    log.warn("주문에 연결된 판매 입찰 정보가 없습니다: 주문ID={}", order.getId());
394	                    return;
395	                }
397	                Style sale = saleBid.getSale();
398	                if (sale == null) {
399	                    log.warn("판매 입찰에 연결된 판매 정보가 없습니다: 판매입찰ID={}", saleBid.getId());
400	                    return;
401	                }
403	                sendNotifications(order, sale);
404	                sale.updateStatus(StyleStatus.SOLD);
405	                log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
406	                return;
407	            }
410	            Style sale = orderBid.getSale();
411	            if (sale == null) {
412	                log.warn("주문 입찰에 연결된 판매 정보가 없습니다: 주문입찰ID={}", orderBid.getId());
413	                return;
414	            }
416	            sendNotifications(order, sale);
419	            sale.updateStatus(StyleStatus.SOLD);
420	            log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
421	        } catch (Exception e) {
423	            log.error("결제 관련 알림 및 판매 상태 업데이트 중 오류 발생: 주문ID={}, 오류={}",
424	                    order.getId(), e.getMessage(), e);
425	        }
426	    }
434	    private void sendNotifications(Faq order, Style sale) {
435	        try {
436	            Product buyer = order.getUser();
437	            if (buyer != null) {
438	                notificationCommandService.createNotification(
439	                        buyer.getId(),
440	                        PaymentCategory.SHOPPING,
441	                        PaymentType.BID,
442	                        "결제가 완료되었습니다. 주문 ID: " + order.getId()
443	                );
444	                log.debug("구매자 알림 전송 완료: 구매자ID={}", buyer.getId());
445	            }
447	            Product seller = sale.getSeller();
448	            if (seller != null) {
449	                notificationCommandService.createNotification(
450	                        seller.getId(),
451	                        PaymentCategory.SHOPPING,
452	                        PaymentType.BID,
